The following code implementation has a time complexity of O(n^2).

#include <iostream>
using namespace std;

void bubble_sort(int nums[], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (nums[j] > nums[j+1]) {
                swap(nums[j], nums[j+1]);
            }
        }
    }
}

int main() {
