To achieve this, you can follow these steps:

1. Install the EPPlus NuGet package, if you haven't already.
2. Read the Excel file and retrieve the specified worksheet containing the table.
3. Iterate through the table rows and add data to the respective lists.

Here's the sample code:

```csharp
using OfficeOpenXml;
using OfficeOpenXml.Table;
using System;
using System.Collections.Generic;
using System.IO;

namespace EPPlusTest
{
    class Program
    {
        public class ExcelData
        {
            public int Id { get; set; }
            public string Name { get; set; }
            public string Gender { get; set; }
        }

        static void Main(string[] args)
        {
            FileInfo file = new FileInfo(@"C:\ExcelFile.xlsx");

            using (ExcelPackage package = new ExcelPackage(file))
            {
                ExcelWorksheet sheet = package.Workbook.Worksheets[0];

                ExcelTable table = sheet.Tables.First();

                List<ExcelData> data = new List<ExcelData>();

                int rowStart = table.Address.Start.Row + 1; // Start at the row after the header.
                int rowEnd = table.Address.End.Row;

                // Iterate through table rows and map them to ExcelData objects.
                for (int row = rowStart; row <= rowEnd; row++)
                {
                    data.Add(new ExcelData
                    {
                        Id = sheet.Cells[row, table.Columns["Id"].Position + 1].GetValue<int>(),
                        Name = sheet.Cells[row, table.Columns["Name"].Position + 1].GetValue<string>(),
